/* Standalone checker: clean-room STR/BS VLC decoder (pe_vlc_decode.c, fresh author) vs the original's outputs.
 *   cc -std=c99 -Wall -Wextra -Werror -Ipc_port/include -Ipc_port/tests pc_port/tools/pe_mdec_vlc_vectors_check.c pc_port/platform/pe_vlc_decode.c -o check
 *   PE_DISC1_BIN=<Disc 1 .bin> ./check
 * Vectors: pc_port/tests/retail_mdec_vlc_cases.h (generated by
 * pc_port/tools/pe_mdec_vlc_vectors.py from the original code, black-box).
 * Exit 0 = 0 mismatches.  pc_port/tools/pe_mdec_vlc_check.sh also runs a mutant. */
#include <stdint.h>
#include "pe_vlc_decode.h"
#include "retail_mdec_vlc_cases.h"
#include "mdec_vlc_check_core.h"

static int ReadRaw(void *ctx, uint32_t lba, uint8_t raw[2352])
{
    FILE *f = ctx;
    if (fseek(f, (long)lba * 2352L, SEEK_SET)) return 0;
    return fread(raw, 1, 2352, f) == 2352;
}

int main(void)
{
    const char *disc = getenv("PE_DISC1_BIN");
    char err[256] = "";
    unsigned nr, ns, nk, nh;
    FILE *f;
    if (!disc || !(f = fopen(disc, "rb"))) { fprintf(stderr, "set PE_DISC1_BIN to the Disc 1 .bin\n"); return 2; }
    if (!MdecVlcCheckAll(ReadRaw, f, err, sizeof(err), &nr, &ns, &nk, &nh)) {
        printf("MISMATCH: %s\n", err); fclose(f); return 1;
    }
    fclose(f);
    printf("PASS: %u real frames + %u synthetic exact (output, length, fitted input cursor), %u original-hang vectors, 0 mismatches\n", nr, ns, nh); (void)nk;
    return 0;
}
